REVOKE ALL ON public.logistics_profiles,public.ports,public.shipping_routes,public.shipping_rates,public.transporter_assets,public.transporter_service_areas,public.logistics_documents,public.logistics_activity FROM anon,authenticated;
GRANT SELECT,INSERT ON public.logistics_profiles,public.ports,public.shipping_routes,public.shipping_rates,public.transporter_assets,public.transporter_service_areas,public.logistics_documents TO authenticated;
GRANT SELECT ON public.logistics_activity TO authenticated;
CREATE FUNCTION public.validate_logistics_service() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ DECLARE k text; BEGIN IF TG_TABLE_NAME='shipping_routes' THEN SELECT kind INTO k FROM public.logistics_profiles WHERE organization_id=NEW.organization_id AND entity_id=NEW.shipping_agent_entity_id; IF k NOT IN ('shipping_agent','both') OR k IS NULL THEN RAISE EXCEPTION 'Shipping agent required'; END IF; ELSIF TG_TABLE_NAME IN ('transporter_assets','transporter_service_areas') THEN SELECT kind INTO k FROM public.logistics_profiles WHERE organization_id=NEW.organization_id AND entity_id=NEW.transporter_entity_id; IF k NOT IN ('transporter','both') OR k IS NULL THEN RAISE EXCEPTION 'Transporter required'; END IF; ELSIF TG_TABLE_NAME='shipping_rates' AND NEW.asset_id IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.transporter_assets t JOIN public.transporter_service_areas a ON a.organization_id=t.organization_id AND a.transporter_entity_id=t.transporter_entity_id WHERE t.organization_id=NEW.organization_id AND t.id=NEW.asset_id AND a.id=NEW.service_area_id) THEN RAISE EXCEPTION 'Vehicle and service area transporter mismatch'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_logistics_service() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_route_agent BEFORE INSERT ON public.shipping_routes FOR EACH ROW EXECUTE FUNCTION public.validate_logistics_service();
CREATE TRIGGER validate_asset_transporter BEFORE INSERT ON public.transporter_assets FOR EACH ROW EXECUTE FUNCTION public.validate_logistics_service();
CREATE TRIGGER validate_area_transporter BEFORE INSERT ON public.transporter_service_areas FOR EACH ROW EXECUTE FUNCTION public.validate_logistics_service();
CREATE TRIGGER validate_rate_vehicle BEFORE INSERT ON public.shipping_rates FOR EACH ROW EXECUTE FUNCTION public.validate_logistics_service();